    },
  });

  const field = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement>) => {
    set(e.target.value);
    save.reset();
  };

  const dueTotal = (p: Period) => {
    if (p.closed && p.closedTotal !== null) return p.closedTotal;
    const grades = new Map((people.data ?? []).map((person) => [person.id, person.grade]));
    return sumDues(
      (claims.data ?? [])
        .filter((c) => counts(c) && periodOf([p], c.date) !== undefined)
        .map((c) => fixedDue(c) ?? due(c.amount, rateFor(rates.data, grades.get(c.personId), c.date))),
    );
  };

  return (
    <section data-testid="periods">
      <form
        data-testid="period-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            {g} <strong data-testid={`rate-current-${g}`}>{rateFor(rates.data, g, today.data?.today) ?? 'n/a'}</strong>{' '}
          </span>
        ))}
      </p>
      {rates.isError && <p data-testid="rates-error">{rates.error.message}</p>}
    </section>
  );
}

/** Each person's due-total, by person id: the sum of the figures of their claims that count (a
 *  settled claim's frozen due, else the figure their last statement bound it to, else its live due),
 *  skipping those with none; 'n/a' when no rate for their grade is in force on the sheet's today and
 *  no counting claim of theirs keeps a fixed figure. */
function useDueTotals(sheetId: string): Map<number, string> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
  const totals = new Map<number, string>();
  for (const p of people.data ?? []) {
    const counting = (claims.data ?? []).filter((c) => c.personId === p.id && counts(c));
    const rated = rateFor(rates.data, p.grade, today.data?.today) !== undefined;
    totals.set(p.id, rated || counting.some((c) => fixedDue(c) !== null)
      ? sumDues(counting.map((c) => fixedDue(c) ?? due(c.amount, rateFor(rates.data, p.grade, c.date))))
      : 'n/a');
  }
  return totals;
}

function PersonDueTotal({ sheetId, personId }: { sheetId: string; personId: number }) {
  const totals = useDueTotals(sheetId);
  return <td data-testid="person-due-total">{totals.get(personId) ?? ''}</td>;
}

/** The sheet's due-total: everyone's due-total added up, skipping 'n/a'. */
function DueTotal({ sheetId }: { sheetId: string }) {
  const totals = useDueTotals(sheetId);
  return (
    <p>
      Due total: <strong data-testid="rollup-due-total">{sumDues([...totals.values()])}</strong>
    </p>
  );
}

export const contributions = [
  SheetBody.fill({ order: 5, Component: ({ sheetId }) => <Rates sheetId={sheetId} /> }),
  PersonColumnHead.fill({ order: 20, Component: () => <th>Due</th> }),
  PersonCells.fill({ order: 20, Component: PersonDueTotal }),
  SheetBody.fill({ order: 30, Component: ({ sheetId }) => <DueTotal sheetId={sheetId} /> }),
];

